package com.taller.portal.service;
import com.taller.portal.dto.StatusDtos.*; import com.taller.portal.model.*; import com.taller.portal.repository.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
/** Fachada CRUD de Status; autoriza y normaliza todas las operaciones. */ @Service public class StatusFacade { private final StatusRepository repo; public StatusFacade(StatusRepository repo){this.repo=repo;} private void admin(Authentication a){if(a==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_"+RoleName.ADMINISTRADOR_SISTEMA)))throw new AccessDeniedException("Solo Administrador del Sistema puede gestionar estatus");} private String valor(String x){return x.trim().toUpperCase(Locale.ROOT);} private Fila fila(StatusCatalog x){return new Fila(x.id,x.strValor,x.strDescripcion);} @Transactional(readOnly=true) public Pagina listar(int p,int n,String o,String d,Authentication a){admin(a);if(!Set.of("id","strValor","strDescripcion").contains(o))throw new IllegalArgumentException("Columna de orden inválida");int s=Math.min(Math.max(n,1),10);var r=repo.findAll(PageRequest.of(Math.max(p,0),s,Sort.by("desc".equalsIgnoreCase(d)?Sort.Direction.DESC:Sort.Direction.ASC,o)));return new Pagina(r.map(this::fila).getContent(),p,s,r.getTotalElements(),r.getTotalPages());} @Transactional(readOnly=true) public Fila uno(Long id,Authentication a){admin(a);return fila(repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Estatus no encontrado")));} @Transactional public Fila crear(Entrada e,Authentication a){admin(a);String v=valor(e.strValor()),d=e.strDescripcion().trim();if(repo.existsByStrValorIgnoreCaseOrStrDescripcionIgnoreCase(v,d))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código o descripción ya existe");StatusCatalog x=new StatusCatalog();x.strValor=v;x.strDescripcion=d;return fila(repo.save(x));} @Transactional public Fila actualizar(Long id,Entrada e,Authentication a){admin(a);StatusCatalog x=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Estatus no encontrado"));String v=valor(e.strValor()),d=e.strDescripcion().trim();if(Set.of(StatusValues.ACTIVO,StatusValues.SUSPENDIDO,StatusValues.CANCELADO).contains(x.strValor)&&!x.strValor.equals(v))throw new IllegalArgumentException("No se puede cambiar el código de un estatus base");if((!x.strValor.equalsIgnoreCase(v)||!x.strDescripcion.equalsIgnoreCase(d))&&repo.existsByStrValorIgnoreCaseOrStrDescripcionIgnoreCase(v,d))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código o descripción ya existe");x.strValor=v;x.strDescripcion=d;return fila(repo.save(x));} @Transactional public void eliminar(Long id,Authentication a){admin(a);StatusCatalog x=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Estatus no encontrado"));if(Set.of(StatusValues.ACTIVO,StatusValues.SUSPENDIDO,StatusValues.CANCELADO).contains(x.strValor))throw new ResponseStatusException(HttpStatus.CONFLICT,"No se puede eliminar un estatus base");if(repo.referenciado(id))throw new ResponseStatusException(HttpStatus.CONFLICT,"El estatus está en uso");repo.delete(x);} }
